/** Complete editable interpretations of the owner's six supplied reference sites.
 * Source HTML, CSS and interactions were inspected before authoring these trees.
 * Photographs are always looked up within their own reference's asset manifest.
 */
import type { Words } from "../../types";
import { BTN, H, T, type TK } from "../lib";
import { cols, el, grid, row, sec, stack, t, type Node, type Style as Css } from "../tree";
import type { Template } from "./types";
import { defineReference, merchantWords, referenceStyle, sourceAsset, sourceHeader, sourcePicture } from "./referenceShared";

const link = (label: string, href: string) => ({ label: t(label), href });
const rule = (k: TK, color = "border") => el(k, "divider", {}, { style: { color } });
const micro = (k: TK, text: Words, style: Css = {}) => T(k, text, { size: 11, style: { letterSpacing: 1.8, caps: "upper", ...style }, motion: false });
const pic = (k: TK, n: number, file: string, alt: string, style: Css = {}) => sourcePicture(k, n, file, t(alt), style);
const label = (k: TK, text: string | Words, color = "accent") => micro(k, typeof text === "string" ? t(text) : text, { color });
function deck(k: TK, panels: Node[], labels: Words[], style: Css, phone: Css = {}): Node {
  const node = el(k, "deck", { labels: Object.fromEntries(panels.map((panel, i) => [panel.id, labels[i]])), initial: 0, transition: "slide", duration: .65, arrows: true, dots: true, menu: true }, { style, phone });
  node.children = panels;
  return node;
}

